public void startSetAlarmAndPromptConfigThread() {
    LogUtil.i("<literal omitted>", "<literal omitted>");
    if (this.mActivity.mDeviceInfo != null) {
        this.mSetAlarmAndPromptConfigThreadID++;
        AlarmAndPromptConfigThread alarmAndPromptConfigThread = new AlarmAndPromptConfigThread(this.mAiEnable, this.mAiSwitch, false, this.mHasAlarmConfig, this.mBMainAlarmSwitch, this.mMotionAlarmSwitch, this.mHasVoicePromptsConfig, this.mBAlarmVoiceSwitch, this.mBVoicePromptsMainSwitch, this.mLanguage, this.mHasExIOConfig, this.mIOMode, this.mCurrentSetAlarmTimeList, sLocalAreaArray, this.mMotionAlarmFrame, this.mMotionLightDetection, this.mActivity.mDeviceInfo, this.mSetAlarmAndPromptConfigThreadID);
